result = {'main': {'accepted': accepted, 'rejected': rejected, 'remaining': remaining}}","effects":""},"feedback":{"code":"GOAL_MISMATCH","input":{"stock":15,"rows":[{"id":"i201_03","priority":3,"qty":6},{"id":"i201_02","priority":4,"qty":7},{"id":"i201_05","priority":1,"qty":7},{"id":"i201_00","priority":4,"qty":5},{"id":"i201_04","priority":1,"qty":2},{"id":"i201_01","priority":4,"qty":3},{"id":"i201_06","priority":4,"qty":5}]},"pending":["write:main","prepare","commit","notify","cleanup"],"wrong_content":[],"seed":201}}}
